  const auto reference=stage.at("source_capture_checkpoint");receipt["checkpoint"]=reference;const auto manifest_file=coarse_resume_detail::verified_ref(reference,stage_root),root=manifest_file.parent_path();const auto cp=eventio::read_json(manifest_file);
  if(cp.at("schema")!="rinkfit.joint_source_capture_checkpoint.v1"||cp.at("quality_accepted")!=false||cp.at("formal_Phase_I_II_passed")!=false||cp.at("new_true_RS_or_finite_Query_rebinding_performed")!=false||cp.at("source_UV_E_W_Query_membership_changed")!=false||cp.at("station_is_current_Ceres_parameter_state")!=true||cp.at("row_alpha_path_are_unchanged_numerical_seeds")!=true||cp.at("optimizer_internal_trust_region_history_saved")!=false)throw std::runtime_error("not a genuine source-capture primal checkpoint");
