  if(cp.at("source_packet_sha256")!=packet_sha||cp.at("input_packet_sha256")!=packet_sha||b.packet.source_hash!=packet_sha||cp.at("raw_rows")!=count||start>count)throw std::runtime_error("checkpoint current source packet/raw count mismatch");
  const auto&deps=cp.at("dependencies");coarse_resume_detail::dependencies(deps,root);if(cp.contains("pinned_original_manifest")){const auto original=eventio::read_json(coarse_resume_detail::verified_ref(cp.at("pinned_original_manifest"),root));for(const auto*key:{"schema","generation","iteration","objective_mode","source_packet_sha256","input_packet_sha256","raw_rows","dependencies","initial_nuisance_manifest"})if(original.at(key)!=cp.at(key))throw std::runtime_error("pinned checkpoint changed original runtime identity");for(const auto*name:{"model.json","station.f64","row.f64","alpha.f64","path.u32"})if(original.at("files").at(name).at("sha256")!=cp.at("files").at(name).at("sha256")||original.at("files").at(name).at("size_bytes")!=cp.at("files").at(name).at("size_bytes"))throw std::runtime_error("pinned checkpoint changed original complete primal");}
