  const auto old_stage_file=coarse_resume_detail::verified_ref(deps.at("stage"),root);const auto old_stage=eventio::read_json(old_stage_file);coarse_resume_detail::dependencies(old_stage,old_stage_file.parent_path());const auto old_mode=old_stage.value("source_capture_feasibility",false)?std::string("source_capture_feasibility"):std::string("source_capture_engineering");
