  for(const auto*name:{"station.f64","row.f64","alpha.f64","path.u32"}){auto ref=initial.at("files").at(name);ref["file"]=(initial_file.parent_path()/name).string();const auto seed_file=coarse_resume_detail::verified_ref(ref,initial_file.parent_path());if(std::filesystem::file_size(seed_file)!=count*(std::string(name)=="path.u32"?sizeof(std::uint32_t):sizeof(double)))throw std::runtime_error("checkpoint initial complete auxiliary byte count mismatch");}
  const auto&files=cp.at("files");const auto cp_model=coarse_resume_detail::verified_ref(files.at("model.json"),root);
