  for(const auto*name:{"row.f64","alpha.f64","path.u32"})if(files.at(name).at("sha256")!=initial.at("files").at(name).at("sha256"))throw std::runtime_error("checkpoint row/alpha/path must be unchanged original numeric seeds");
