  const auto&shot=b.model.shots.at(b.model.shot_map.at("s01"));protected_blocks.insert(shot.reference_angles_block);protected_blocks.insert(shot.control_sources.begin(),shot.control_sources.end());
  for(auto it=b.model.source_json.at("s01_block_map").begin();it!=b.model.source_json.at("s01_block_map").end();++it)protected_blocks.insert(it.value().get<int>());
