  for(const auto*key:{"s01_affine_recovery_corrections","s01_block_map"})if(before.at(key)!=b.model.source_json.at(key))throw std::runtime_error("checkpoint S01 projection metadata changed");
  if(before.at("shots").at("s01")!=b.model.source_json.at("shots").at("s01")||before.at("rigs").at("main").at("camera")!=b.model.source_json.at("rigs").at("main").at("camera")||before.at("materials")!=b.model.source_json.at("materials"))throw std::runtime_error("checkpoint complete S01 camera/material chart metadata changed");
  // New run owns an honest initialization state. Fixed original seeds are
