  const auto aux=out/"initial_nuisance_state";if(std::filesystem::exists(aux))throw std::runtime_error("checkpoint resume cannot overwrite a run initial nuisance state");std::filesystem::create_directories(aux);eventio::Json initial_files;
  for(const auto*name:{"station.f64","row.f64","alpha.f64","path.u32"}){const auto source=coarse_resume_detail::verified_ref(files.at(name),root);coarse_resume_detail::copy_or_link(source,aux/name,std::string(name)!="station.f64");initial_files[name]={{"sha256",eventio::file_sha256(aux/name)},{"size_bytes",std::filesystem::file_size(aux/name)}};if(initial_files.at(name).at("sha256")!=files.at(name).at("sha256"))throw std::runtime_error("checkpoint initial state copy/link changed bytes");}
