  b.station=std::move(station);b.row=std::move(row);b.alpha=std::move(alpha);for(std::size_t i=0;i<count;++i){auto&o=b.packet.rows[i];o.station=b.station[i];o.row=b.row[i];o.alpha=b.alpha[i];o.path=int(path[i]);}
